declarations.HEAD:
def backgroundSample {n : ℕ} {Ω : Type u}
    (B : Finset (Fin n)) (e : Fin B.card ≃ {i : Fin n // i ∈ B})
    (x : Fin n → Ω) : Fin B.card → Ω

declarations.definitionRhs:
let R : ℝ := Real.sqrt
  (Shao.OQ6.FiniteRows.jackknifeSq (Shao.OQ5.P51.sampledKernel n g r x));
@ite ℝ (R = 0) (Classical.propDecidable (R = 0)) (0 : ℝ)
  (Real.sqrt (n : ℝ) *
    Shao.OQ6.FiniteRows.uStatistic (Shao.OQ5.P51.sampledKernel n g r x) / R)

declarations.HEAD:
private theorem background_index_mem {n : ℕ}
    (B : Finset (Fin n)) (e : Fin B.card ≃ {i : Fin n // i ∈ B})
    (j : Fin B.card) : (e j).val ∈ B

private theorem background_index_injective {n : ℕ}
    (B : Finset (Fin n)) (e : Fin B.card ≃ {i : Fin n // i ∈ B}) :
    Function.Injective (fun j : Fin B.card => (e j).val)

theorem physicalStatistic_background_guarded {n : ℕ} {Ω : Type u}
    (B : Finset (Fin n)) (e : Fin B.card ≃ {i : Fin n // i ∈ B})
    (g : Ω → ℝ) (r : Ω → Ω → ℝ) (x : Fin n → Ω)
    (hsym : ∀ a b : Ω, r a b = r b a)
    (hn : 4 ≤ n) (hm : 4 ≤ B.card) :
    physicalStatistic B.card g (scaledResidual B r) (backgroundSample B e x) =
      let s : ℝ := backgroundStudentizer B (fun i : Fin n => g (x i))
        (fun i j : Fin n => r (x i) (x j));
      @ite ℝ (s = 0) (Classical.propDecidable (s = 0)) (0 : ℝ)
        (backgroundNumerator B (fun i : Fin n => g (x i))
          (fun i j : Fin n => r (x i) (x j)) / s)

theorem card_ge_four_of_half_sample {n : ℕ}
    (B : Finset (Fin n)) (hn : 8 ≤ n) (hhalf : n ≤ 2 * B.card) :
    4 ≤ B.card
